// ─── File: ArchitectureAdvisorDemo.java ───
// Models the major architecture styles and recommends one for a banking scenario.
import java.util.*;
import java.util.logging.*;

public class ArchitectureAdvisorDemo {
    private static final Logger log = Logger.getLogger("Arch");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StyleAdvisor advisor = new StyleAdvisor();

        Scenario smallFeature = new Scenario("New savings-goal feature", 2, "low", false);
        Scenario tradingDesk = new Scenario("Market-open order burst", 30, "extreme", false);
        Scenario settlementMesh = new Scenario("Inter-bank settlement", 10, "medium", true);

        advisor.recommend(smallFeature);
        advisor.recommend(tradingDesk);
        advisor.recommend(settlementMesh);
    }
}

// ─── Would be in dto/Scenario.java ───
class Scenario {
    final String name; final int teamSize; final String loadProfile; final boolean needsDecentralization;
    Scenario(String name, int teamSize, String loadProfile, boolean needsDecentralization) {
        this.name = name; this.teamSize = teamSize; this.loadProfile = loadProfile;
        this.needsDecentralization = needsDecentralization;
    }
}

// ─── Would be in model/ArchitectureStyle.java ───
abstract class ArchitectureStyle {
    abstract String name();
    abstract String solves();
    abstract String mainCost();
    abstract boolean fits(Scenario s);
}

// ─── Would be in model/Monolith.java ───
class Monolith extends ArchitectureStyle {
    String name() { return "Monolith"; }
    String solves() { return "Simplicity: one build, one deploy, in-process calls, easy transactions"; }
    String mainCost() { return "Scales as one unit; coupling grows with size"; }
    boolean fits(Scenario s) { return s.teamSize <= 3 && s.loadProfile.equals("low") && !s.needsDecentralization; }
}

// ─── Would be in model/ModularMonolith.java ───
class ModularMonolith extends ArchitectureStyle {
    String name() { return "Modular Monolith"; }
    String solves() { return "Maintainability + clean boundaries with single-deploy simplicity"; }
    String mainCost() { return "One deploy; discipline needed to keep module boundaries"; }
    boolean fits(Scenario s) { return s.teamSize <= 10 && !s.loadProfile.equals("extreme") && !s.needsDecentralization; }
}

// ─── Would be in model/Microservices.java ───
class Microservices extends ArchitectureStyle {
    String name() { return "Microservices"; }
    String solves() { return "Independent deploy/scale, team autonomy, polyglot tech"; }
    String mainCost() { return "Distributed complexity, eventual consistency, heavy ops"; }
    boolean fits(Scenario s) { return s.teamSize > 10 && !s.needsDecentralization; }
}

// ─── Would be in model/SpaceBased.java ───
class SpaceBased extends ArchitectureStyle {
    String name() { return "Space-Based"; }
    String solves() { return "Extreme bursty load by removing the DB bottleneck (in-memory grid)"; }
    String mainCost() { return "In-memory grid complexity, async DB flush risk"; }
    boolean fits(Scenario s) { return s.loadProfile.equals("extreme"); }
}

// ─── Would be in model/PeerToPeer.java ───
class PeerToPeer extends ArchitectureStyle {
    String name() { return "Peer-to-Peer"; }
    String solves() { return "Decentralization as a hard requirement (no central authority)"; }
    String mainCost() { return "Harder consistency/ordering, no single point of control"; }
    boolean fits(Scenario s) { return s.needsDecentralization; }
}

// ─── Would be in service/StyleAdvisor.java ───
class StyleAdvisor {
    private static final Logger log = Logger.getLogger("Arch");
    private final List<ArchitectureStyle> styles = List.of(
            new PeerToPeer(), new SpaceBased(), new Microservices(),
            new ModularMonolith(), new Monolith());
    void recommend(Scenario s) {
        // Priority order: hard constraints (decentralization, extreme load) first.
        for (ArchitectureStyle style : styles) {
            if (style.fits(s)) {
                log.info(() -> "Scenario '" + s.name + "' (team=" + s.teamSize
                        + ", load=" + s.loadProfile + ", decentralized=" + s.needsDecentralization
                        + ") → " + style.name());
                log.info(() -> "   Solves: " + style.solves());
                log.info(() -> "   Cost:   " + style.mainCost());
                return;
            }
        }
        log.warning(() -> "No clear fit for '" + s.name + "' — default to Modular Monolith");
    }
}

